{
  "operations": [
    {
      "op": "add",
      "unit": {
        "label": "Autorisation d'une lettre d'intention — vente potentielle d'une partie du lot 6 191 770, rue du Bateau",
        "stage": "inconnu",
        "procedure": null,
        "objet": "6 191 770",
        "page": 8,
        "citation": "• DE TRANSMETTRE une lettre d'intention pour la signature éventuelle d'une\npromesse de vente et d'achat pour une partie du lot 6 191 770 à l'entreprise ;",
        "anchor": "lot 6 191 770"
      },
      "reason": "La résolution 117-2026 autorise une démarche foncière explicite par lettre d'intention, sans décider une vente définitive."
    },
    {
      "op": "add",
      "unit": {
        "label": "Adoption du règlement 760-2026 — modification des grandes affectations du plan d'urbanisme",
        "stage": "adoption",
        "procedure": null,
        "objet": "760-2026",
        "page": 9,
        "citation": "• QUE le règlement #760-2026 intitulé « Règlement modifiant le plan d'urbanisme\n#387-2007 - Grandes affectations », soit adopté",
        "anchor": "règlement #760-2026"
      },
      "reason": "La résolution 118-2026 adopte ce règlement d'urbanisme, tandis que l'avis de motion et la consultation du 23 avril ne sont que des rappels historiques."
    },
    {
      "op": "add",
      "unit": {
        "label": "Adoption du règlement 761-2026 — usages de la zone 14-I et création de la zone 21-H",
        "stage": "adoption",
        "procedure": null,
        "objet": "761-2026",
        "page": 9,
        "citation": "• QUE le règlement #761-2026 intitulé « Règlement modifiant le règlement\n#389-2007 afin d'y modifier les usages permis dans la zone 14-I et la création de\nla zone 21-H », soit adopté",
        "anchor": "règlement #761-2026"
      },
      "reason": "La résolution 119-2026 constate l'adoption du règlement modifiant le zonage, sans créer d'unités supplémentaires pour les étapes antérieures rappelées."
    },
    {
      "op": "add",
      "unit": {
        "label": "Approbation du plan de développement et de lotissement — lot 3 592 103, prolongement de la rue Thibodeau",
        "stage": "adoption",
        "procedure": null,
        "objet": "3 592 103",
        "page": 10,
        "citation": "• D'APPROUVER le plan d'aménagement produit par la firme « Giroux Arpentage »,\nconcernant le développement du lot 3 592 103 ;",
        "anchor": "lot 3 592 103"
      },
      "reason": "La résolution 120-2026 approuve un plan de lotissement et de développement prévoyant explicitement le prolongement de la rue Thibodeau pour des habitations unifamiliales."
    },
    {
      "op": "add",
      "unit": {
        "label": "Recommandation favorable à la CPTAQ — projet éolien Lotbinière Ndakina",
        "stage": "inconnu",
        "procedure": null,
        "objet": "Projet éolien Lotbinière Ndakina",
        "page": 14,
        "citation": "• QUE la Municipalité de Sainte-Croix recommande à la Commission d’approuver la\nDemande",
        "anchor": "recommande à la Commission d’approuver"
      },
      "reason": "La résolution 121-2026 formule une recommandation municipale sur une demande explicite d'implantation en zone agricole, et non une autorisation acquise de la CPTAQ."
    },
    {
      "op": "add",
      "unit": {
        "label": "Engagement à octroyer des droits fonciers municipaux — projet éolien Lotbinière Ndakina",
        "stage": "inconnu",
        "procedure": null,
        "objet": "droits fonciers municipaux",
        "page": 14,
        "citation": "• QUE Ia Municipalité confirme son engagement à l'octroi des droits fonciers sur les\nterres du domaine municipal qui pourront être requises pour la réalisation du Projet ;",
        "anchor": "l'octroi des droits fonciers"
      },
      "reason": "La résolution 121-2026 constate aussi un engagement foncier explicite sur les terres municipales, distinct de la recommandation à la CPTAQ, sans établir qu'une servitude est déjà conclue."
    },
    {
      "op": "add",
      "unit": {
        "label": "Approbation des plans et devis préliminaires — développement du lot 3 592 103, rue Thibodeau",
        "stage": "adoption",
        "procedure": null,
        "objet": "3 592 103",
        "page": 17,
        "citation": "• D'APPROUVER au promoteur les plans et devis préliminaires de l'entreprise\n« Apex Expert Conseil inc. », concernant le développement du lot 3 592 103 ;",
        "anchor": "lot 3 592 103"
      },
      "reason": "La résolution 126-2026 approuve distinctement les plans et devis préliminaires d'une ouverture de rue destinée au développement résidentiel, sans certifier la conformité finale du projet."
    }
  ]
}
